    pub fn should_pre_filter(
        &self,
        filter: &Filter,
        limit: Option<usize>,
        hw_counter: &HardwareCounterCell,
    ) -> OperationResult<bool> {
        let query_cardinality = self
            .payload_index
            .estimate_cardinality(filter, hw_counter)?;

        let available_points = self.id_tracker.available_point_count() + 1;
        let check_probability =
            (query_cardinality.exp as f64 + 1.0) / available_points as f64;
        let exp_stream_checks =
            (limit.unwrap_or(available_points) as f64 / check_probability) as usize;

        Ok(query_cardinality.exp < exp_stream_checks)
    }
